              hsvV = 1 - clamp01(((py - (p and p.Y or 0)) / ((sz and sz.Y) or 1)))
              refreshUI()
            end
            local function updateFromHue(px)
              local p, sz = hue.AbsolutePosition, hue.AbsoluteSize
